// Classic library pattern pre-ES6
var MyLib = (function() {
  var _private = 'secret';

  function _helper() { return _private; }

  return {
    publicMethod: function() { return _helper(); }
  };
})();

MyLib.publicMethod(); // 'secret'
MyLib._private;       // undefined

const UserModule = (function() {
  let _users = [];

  function _validate(user) {
    return user && user.name;
  }

  function addUser(user) {
    if (_validate(user)) _users.push(user);
  }

  function getUsers() { return [..._users]; }

  // Reveal only what's needed
  return { addUser, getUsers };
})();

