const bank = (function() {
  let bal = 100;
  return {
    deposit: (n) => { bal += n; },
    withdraw: (n) => { bal -= n; },
    balance: () => bal
  };
})();
bank.deposit(50);
bank.withdraw(30);
bank.deposit(10);
console.log(bank.balance());
